/**
 * Typed access to the cab snapshots generated by `scripts/sync-cabs-snapshot.mjs`
 * (copies of the live /cars/ pages — never edit by hand). Validated at build time.
 */
import "server-only";
import { z } from "zod";
import formData from "./cabs/form.json";
import indexPage from "./cabs/_index.json";
import cabIndexFile from "./cabs/index.json";

const inlineRun = z.object({ text: z.string(), bold: z.boolean().optional(), href: z.string().optional() });

const cell = z.object({
  text: z.string(),
  colSpan: z.number().int().optional(),
  rowSpan: z.number().int().optional(),
  image: z.object({ src: z.string(), alt: z.string() }).optional(),
});
export type CabTableCell = z.infer<typeof cell>;

const card = z.object({
  title: z.string(),
  href: z.string(),
  image: z.string().nullable(),
  duration: z.string(),
  price: z.object({ label: z.string(), amount: z.string(), unit: z.string() }).optional(),
});

const block = z.discriminatedUnion("type", [
  z.object({ type: z.literal("heading"), level: z.number().int().min(1).max(6), text: z.string() }),
  z.object({ type: z.literal("p"), content: z.array(inlineRun) }),
  z.object({ type: z.literal("list"), ordered: z.boolean(), items: z.array(z.array(inlineRun)) }),
  z.object({ type: z.literal("table"), caption: z.string().optional(), head: z.array(z.array(cell)), rows: z.array(z.array(cell)) }),
  z.object({ type: z.literal("image"), src: z.string(), alt: z.string(), caption: z.string().optional() }),
  z.object({
    type: z.literal("faq"),
    items: z.array(z.object({ question: z.string(), answer: z.array(inlineRun) })),
  }),
  z.object({
    type: z.literal("links"),
    title: z.string().optional(),
    items: z.array(z.object({ label: z.string(), href: z.string() })),
  }),
  z.object({ type: z.literal("cards"), title: z.string().optional(), items: z.array(card) }),
  z.object({
    type: z.literal("routes"),
    columns: z.array(z.object({ title: z.string(), stops: z.array(z.string()) })),
  }),
  z.object({
    type: z.literal("trips"),
    items: z.array(
      z.object({
        number: z.string(),
        title: z.string(),
        duration: z.string(),
        days: z.array(z.object({ marker: z.string(), title: z.string(), text: z.string() })),
        route: z.object({ label: z.string(), text: z.string() }).optional(),
      }),
    ),
  }),
]);
export type CabBlock = z.infer<typeof block>;

const pageSchema = z.object({
  slug: z.string(),
  url: z.string(),
  seo: z.object({ title: z.string().min(1), description: z.string(), canonical: z.string() }),
  heroImage: z.string().nullable(),
  features: z.array(z.string()),
  blocks: z.array(block).min(1),
});
export type CabPage = z.infer<typeof pageSchema>;

const choice = z.object({ placeholder: z.string(), options: z.array(z.string()).min(1) });
const formSchema = z.object({
  cf7FormId: z.string().nullable(),
  pickup: choice,
  drop: choice,
  time: choice,
  vehicle: choice,
  countryCodes: z.array(z.string()).min(1),
  placeholders: z.object({ date: z.string(), name: z.string(), email: z.string(), phone: z.string() }),
  submitLabel: z.string().min(1),
  honeypotLabel: z.string(),
  dateRule: z.object({ minDaysFromToday: z.number(), maxYearsAhead: z.number(), submitFormat: z.string() }),
});
export type CabForm = z.infer<typeof formSchema>;

/** The shared cab booking form (CF7 291), identical on every cab page. */
export const cabForm = formSchema.parse(formData);

/** The /cars/ page. */
export const cabIndex = pageSchema.parse(indexPage);

/** /cars/<slug>/ pages that exist (written by the sync from the live cab sitemap). */
const slugs = z.object({ slugs: z.array(z.string().regex(/^[a-z0-9-]+$/)) }).parse(cabIndexFile).slugs;

export function listCabSlugs(): string[] {
  return [...slugs];
}

export async function getCabPage(slug: string): Promise<CabPage | null> {
  if (!slugs.includes(slug)) return null;
  return pageSchema.parse((await import(`./cabs/${slug}.json`)).default);
}
